<style>
.album-hero{padding:58px 0 66px;background:var(--gradient-cool);border-bottom:1px solid var(--border)}.album-hero-copy{max-width:850px}.album-eyebrow{margin:0 0 12px;color:var(--primary-deep);font-size:12px;font-weight:700;letter-spacing:.25em;text-transform:uppercase}.album-hero h1{margin:0;font-size:clamp(40px,6vw,66px);font-weight:800;line-height:1.06}.album-hero-description{max-width:780px;margin:20px 0 0;color:var(--muted-foreground);font-size:18px;line-height:1.65}.album-back{display:inline-flex;align-items:center;gap:7px;margin-bottom:25px;color:var(--muted-foreground);font-size:14px;font-weight:600}.album-back:hover{color:var(--primary-deep)}.album-content{padding:58px 0 88px}.photo-grid{columns:3 300px;column-gap:22px}.photo{break-inside:avoid;margin:0 0 22px;overflow:hidden;border:1px solid var(--border);border-radius:20px;background:#fff;box-shadow:var(--shadow-soft);transition:.35s var(--ease)}.photo:hover{transform:translateY(-2px);border-color:var(--primary);box-shadow:var(--shadow-elegant)}.photo a{display:block;overflow:hidden}.photo img{display:block;width:100%;height:auto;transition:.45s var(--ease)}.photo:hover img{transform:scale(1.025)}.photo figcaption{padding:15px 18px;color:var(--muted-foreground);font-size:13px;line-height:1.55}.album-empty{padding:30px;border:1px solid var(--border);border-radius:20px;background:var(--muted);color:var(--muted-foreground)}@media(max-width:600px){.album-hero{padding:44px 0 48px}.album-content{padding-top:40px}.photo-grid{columns:1}}
</style>
<section class="album-hero"><div class="wrap"><div class="album-hero-copy"><a class="album-back" href="/idemaclima/galleria">← Torna alla Galleria</a><p class="album-eyebrow">Album fotografico</p><h1><?=e($album['title'])?></h1><?php if(!empty($album['description'])):?><p class="album-hero-description"><?=e($album['description'])?></p><?php endif;?></div></div></section>
<section class="album-content"><div class="wrap"><?php if(!empty($images)):?><div class="photo-grid"><?php foreach($images as $image):?><figure class="photo"><?php if(!empty($image['image_path'])):?><a href="<?=e($image['image_path'])?>" target="_blank" rel="noopener"><img src="<?=e($image['image_path'])?>" alt="<?=e($image['alt_text']?:$album['title'])?>" loading="lazy"></a><?php endif;?><?php if(!empty($image['caption'])):?><figcaption><?=e($image['caption'])?></figcaption><?php endif;?></figure><?php endforeach;?></div><?php else:?><p class="album-empty">Nessuna immagine disponibile in questo album.</p><?php endif;?></div></section>